from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import dijkstra
im=np.asarray(Image.open('/app/target.png').convert('RGB'));B=im.mean(2)<80
X=np.pad(B,1).astype(bool)
for it in range(100):
 changed=0
 for sub in (0,1):
  p2=X[:-2,1:-1];p3=X[:-2,2:];p4=X[1:-1,2:];p5=X[2:,2:];p6=X[2:,1:-1];p7=X[2:,:-2];p8=X[1:-1,:-2];p9=X[:-2,:-2]
  C=p2.astype(np.uint8)+p3+p4+p5+p6+p7+p8+p9
  tr=((~p2&p3).astype(np.uint8)+(~p3&p4)+(~p4&p5)+(~p5&p6)+(~p6&p7)+(~p7&p8)+(~p8&p9)+(~p9&p2))
  cond=(~(p2&p4&p6)&~(p4&p6&p8)) if sub==0 else (~(p2&p4&p8)&~(p2&p6&p8))
  rem=X[1:-1,1:-1]&(C>=2)&(C<=6)&(tr==1)&cond
  changed+=int(rem.sum());X[1:-1,1:-1][rem]=0
 if not changed:break
sk=X[1:-1,1:-1]; ys,xs=np.where(sk); ids=ys*1024+xs; lookup={int(q):i for i,q in enumerate(ids)}
rows=[];cols=[];vals=[]
for i,(y,x) in enumerate(zip(ys,xs)):
 for dy in [-1,0,1]:
  for dx in [-1,0,1]:
   if dy==dx==0:continue
   j=lookup.get(int((y+dy)*1024+x+dx))
   if j is not None: rows.append(i);cols.append(j);vals.append(1.41421356 if dy and dx else 1.)
G=csr_matrix((vals,(rows,cols)),shape=(len(ids),len(ids)))
dist,pred=dijkstra(G,return_predecessors=True,directed=False)
def snap(pt):
 x,y=pt; j=np.argmin((xs-x)**2+(ys-y)**2);return j

def path(a,b):
 ia,ib=snap(a),snap(b); j=ib; out=[]
 while j!=ia and j>=0: out.append((int(xs[j]),int(ys[j])));j=pred[ia,j]
 out.append((int(xs[ia]),int(ys[ia])));out=out[::-1]
 return np.array(out),float(dist[ia,ib]),((int(xs[ia]),int(ys[ia])),(int(xs[ib]),int(ys[ib])))
def rdp(P,eps=3):
 if len(P)<=2:return P
 a=P[0];b=P[-1];v=b-a
 if np.dot(v,v)==0: ds=np.linalg.norm(P-a,axis=1)
 else: ds=np.abs(np.cross(v,P-a)/np.linalg.norm(v))
