 P=np.array(M,bool);inter=(P&T).sum(); uni=(P|T).sum();stray=(P&(Dt>4.5)).sum()/T.sum();print('METRIC',scale,inter/uni,inter/T.sum(),P.sum()/T.sum(),stray)
